actions.script:
if(System.getProperty('stores.qa.disposable')!='true' || !ec.user.isInGroup('ADMIN')) {ec.web.response.setStatus(403);return}
def demo=ec.entity.find('moqui.security.UserAccount').condition('userId','EX_JOHN_DOE').one()
['SHOP_QA_USER','SHOP_QA_VIEW'].each { id ->
 def qa=ec.entity.find('moqui.security.UserAccount').condition('userId',id).one()
 if(!qa || qa.disabled!='Y') throw new IllegalStateException('Fresh synthetic fixture required')
 ['currentPassword','passwordSalt','passwordHashType','passwordBase64'].each {qa.set(it,demo.get(it))};qa.disabled='N';qa.update()
}
ec.web.sendJsonResponse([initialized:true])

if(System.getProperty('stores.qa.disposable')!='true' || !(ec.user.username in ['shops.qa','shops.viewer','john.doe'])) {ec.web.response.setStatus(403);return}
def op=ec.web.parameters.op
if(op in ['resetScope','forgeScope','clearScope']) {ec.user.setPreference('ACTIVE_ORGANIZATION',op=='resetScope'?'SHOP_QA_A':(op=='forgeScope'?'SHOP_QA_B':''));ec.web.sendJsonResponse([changed:true]);return}
def calls=[create:'create#Store',update:'update#Store',hours:'set#OperatingHours',target:'set#StoreTarget',config:'set#StoreConfig',dashboard:'get#StoreDashboard',reconcile:'reconcile#OrgShops',assign:'assign#ShopCounter',profile:'save#StoreProfile',holiday:'add#StoreHoliday',delete:'delete#Store']
if(!calls[op]) {ec.web.response.setStatus(400);return}
def params=new groovy.json.JsonSlurper().parseText(ec.web.parameters.input ?: '{}')
['storeId','organizationPartyId','managerPartyId','facilityId','terminalId'].each {key -> if(params[key] && !params[key].toString().startsWith('SHOP_QA_')) {
 def shop=key=='storeId' ? ec.entity.find('zenith.erp.stores.Store').condition('storeId',params[key]).disableAuthz().one() : null
 if(!shop?.organizationPartyId?.startsWith('SHOP_QA_')) throw new IllegalArgumentException('Synthetic selectors required')
}}
def result=ec.service.sync().name('zenith.stores.StoreServices.'+calls[op]).parameters(params).call()
def errorText=ec.message.getErrorsString();def errors=errorText ? [errorText] : [];ec.message.clearErrors()
ec.web.sendJsonResponse([result:result,errors:errors])
